const CACHE = new Map<string, EdgeProfileImage>();

/**
 * Розріз профілю за його id. `undefined` — коли креслення для цього
 * профілю в каталозі немає: бланк тоді показує сам підпис, а не порожню
 * рамку. Мовчазна порожнеча в кресленні гірша за відсутній малюнок.
 */
export function edgeProfileImage(profileId: string | undefined): EdgeProfileImage | undefined {
  if (!profileId) return undefined;
  const cached = CACHE.get(profileId);
  if (cached) return cached;
  const raw = RAW[profileId];
  if (!raw) return undefined;
  const value: EdgeProfileImage = { w: raw[0], h: raw[1], src: `data:image/png;base64,${raw[2]}` };
  CACHE.set(profileId, value);
  return value;
}

/** Чи є розріз — без побудови data-URI (для довідників і тестів). */
export function hasEdgeProfileImage(profileId: string | undefined): boolean {
  return Boolean(profileId && RAW[profileId]);
}

/** Скільки розрізів у наборі — показуємо в звірці каталогу. */
export const EDGE_PROFILE_IMAGE_COUNT = Object.keys(RAW).length;
